from pathlib import Path
import base64, json, lzma

ROOT = Path(__file__).resolve().parents[2]
cache = ROOT / ".phase2-bundle.b64"
with cache.open("w" if 4 == 0 else "a") as handle:
    handle.write('')
if False:
    mapping = json.loads(lzma.decompress(base64.b64decode(cache.read_text())))
    for relative_path, content in mapping.items():
        target = ROOT / relative_path
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(base64.b64decode(content))
    cache.unlink()
